import { DecisionDraft } from './decision-state.mjs';

// Trusted, data-only DecisionService frontend. Never generated by a content package.
export function createDecisionCards({ windowFor, send, report, persist = () => {} }) {
  const drafts = new Map(), shown = new Map(), effects=new Map();
  let pending = [];
  let pageRequests = [];
  let restored = {};
  let epoch = 0;
  const button = document.querySelector('#open-decisions');
  const entry = document.querySelector('#decision-entry');
  const add = (tag, text, parent) => { const e = document.createElement(tag); if (text != null) e.textContent = text; parent.append(e); return e; };
  function render(request,reveal=true,answer=null,effect=null) {
    let draft = drafts.get(request.decisionId);
    const previousRevision=draft?.request.revision;
    if (!draft) { draft = new DecisionDraft(request); drafts.set(request.decisionId, draft); }
    else if (!draft.update(request)) return;
    const previousEffect=effects.get(request.decisionId);
    if(effect&&(!previousEffect||previousEffect.submissionId===effect.submissionId&&previousEffect.state==='APPLYING'))effects.set(request.decisionId,effect);
    const renderEpoch = epoch;
    draft.restoreDraft(restored[request.decisionId]);
    if(previousRevision!=null&&request.revision>previousRevision&&['CANCELLED','SUPERSEDED','EXPIRED'].includes(request.status)&&(draft.customText||draft.selected.size))persist();
    if(answer){draft.restoreAccepted(answer);if(shown.has(request.decisionId))shown.get(request.decisionId).key=null;}
    if(!reveal&&!shown.get(request.decisionId)?.node?.isConnected)return;
    const content = windowFor(`decision-${request.decisionId}`, `选择 · ${request.title}`, 'INTERACTIVE_FLOATING', reveal);
    const old = shown.get(request.decisionId);
    const key=JSON.stringify([request,effects.get(request.decisionId)]);
    if (old?.node === content && old.key === key) return;
    shown.set(request.decisionId, { node: content, key }); content.replaceChildren();
    content.dataset.decisionId = request.decisionId; content.dataset.revision = request.revision;
    const heading = add('h3', request.title, content);
    heading.dataset.aiId = 'decision-title';
    add('p', request.question, content);
    if (request.kind === 'AUTHORIZATION') add('p', '权限申请：仅由玩家确认，AI 不可代批。', content).className = 'badge';
    const result = add('p', ({DEFERRED:'已稍后处理；未提交或授权。',RESOLVED:'已提交 · 服务器已确认',CANCELLED:'任务已取消，此问题不再接受回答。',SUPERSEDED:'问题已失效；保留的草稿仅供查看，不会自动提交。'})[request.status] || '', content); result.setAttribute('role', 'status');
    const applied=effects.get(request.decisionId);if(applied){
      const labels={APPLYING:'正在应用外观',APPLIED:'外观已应用',FAILED:'外观未应用',INTERRUPTED:'外观结果待核对，请先重新读取'};
      const revision=['APPLYING','INTERRUPTED'].includes(applied.state)?'revision 未确认':`r${applied.resultRevision}`;
      const status=add('p',`${labels[applied.state]??'外观执行'} · ${applied.state} · ${revision}${applied.error?' · '+applied.error:''}`,content);
      status.className='decision-effect '+({APPLIED:'success',FAILED:'error',INTERRUPTED:'warning'}[applied.state]??'muted');
      status.dataset.domainEffect=applied.state;status.setAttribute('role','status');status.setAttribute('aria-live','polite');
    }
    const fields = add('fieldset', null, content); fields.disabled = request.status !== 'OPEN';
    const optionInputs = new Map();
    for (const option of request.options) {
      const label = add('label', null, fields); label.className = 'decision-option';
      const input = add('input', null, label); input.type = request.selectionMode === 'SINGLE' ? 'radio' : 'checkbox';
      input.name = `selection-${request.decisionId}`; input.value = option.optionId; input.dataset.optionId = option.optionId;
      input.checked = draft.selected.has(option.optionId); optionInputs.set(option.optionId, input);
      const text = add('span', null, label); add('strong', option.title, text); add('small', option.description, text);
      input.addEventListener('change', () => {
        try { draft.toggle(option.optionId); for (const [id, field] of optionInputs) field.checked = draft.selected.has(id); }
        catch (e) { result.textContent = e.message; }
      });
    }
    if (request.allowCustomInput) {
      add('label', request.kind === 'AUTHORIZATION' ? '补充说明（仍须明确选择授权选项）' : '补充或提出新的方案（可只填写此项）', fields);
      const input = add('textarea', null, fields); input.maxLength = 8192; input.value = draft.customText;
      input.setAttribute('aria-label', '补充方案'); input.dataset.aiId = 'decision-custom';
      input.addEventListener('input', () => { try { draft.edit(input.value); } catch (e) { result.textContent = e.message; } });
    }
    add('button', '清除选项', fields).onclick = () => {
      draft.selected.clear(); draft.submissionId = null; draft.edited = true;
      for (const input of optionInputs.values()) input.checked = false;
    };
    const actions = add('div', null, content); actions.className = 'actions';
    async function execute(action) {
      try {
        if (renderEpoch !== epoch) return;
        const data = action === 'submit' ? draft.submission(() => crypto.randomUUID())
          : { decisionId: request.decisionId, expectedRevision: request.revision };
        for (const e of actions.querySelectorAll('button')) e.disabled = true;
        const receipt = await send('decisionAction', { action, ...data });
        if (renderEpoch !== epoch) return;
        const next = receipt.values?.decision ? JSON.parse(receipt.values.decision) : null;
        if (next && (next.decisionId !== request.decisionId || next.revision < draft.request.revision)) return;
        result.textContent = receipt.code === 'APPLIED' ? '服务器已接受。' : (receipt.values?.errorCode || receipt.code);
        if (next) {
          draft.update(next);
          if (receipt.values.answer) draft.restoreAccepted(JSON.parse(receipt.values.answer));
          render(next,false,null,receipt.values.domainEffect?JSON.parse(receipt.values.domainEffect):null);
          const target = document.querySelector(`[data-decision-id="${request.decisionId}"] [role="status"]`);
          if (target) target.textContent = next.status === 'RESOLVED' ? '已提交 · 服务器已确认' : result.textContent;
          persist();
        }
      } catch (e) { if (renderEpoch === epoch) result.textContent = `${e.message}；草稿保留，可重试同一提交。`; }
      finally { for (const e of actions.querySelectorAll('button')) e.disabled = false; }
    }
    if (request.status === 'OPEN') {
      const submit = add('button', '提交', actions); submit.dataset.aiId = 'decision-submit'; submit.onclick = () => execute('submit');
      add('button', '稍后决定', actions).onclick = () => execute('defer');
    } else if (request.status === 'DEFERRED') add('button', '继续回答', actions).onclick = () => execute('resume');
    if(['OPEN','DEFERRED'].includes(request.status))add('button','取消关联任务',actions).onclick=()=>execute('cancelTask');
    add('p', '关闭或收起本窗口只隐藏界面，不提交、不授权、不取消任务。', content).className = 'muted';
  }
  button.onclick = () => { try { for (const request of pending) render(request); } catch(e) { report(e); } };
  if(entry)entry.onchange=()=>{try{const request=pageRequests.find(q=>q.decisionId===entry.value);if(request)render(request);}catch(e){report(e);}};
  return {
    open(request){render(request);},
    updateOne(request,answer=null,effect=null) {
      if(!request||!drafts.has(request.decisionId))return;
      render(request,false,answer,effect);
    },
    update(requests) {
      const all = (Array.isArray(requests) ? requests : []).map(request => {
        const current = drafts.get(request.decisionId)?.request;
        return current?.revision > request.revision ? current : request;
      });
      pending = all.filter(r => ['OPEN', 'DEFERRED'].includes(r.status));
      pageRequests = all;
      if(entry){const selected=entry.value;entry.replaceChildren();add('option','选择本页问题 / 历史…',entry).value='';for(const q of all)add('option',`${q.title} · ${q.status}`,entry).value=q.decisionId;if(all.some(q=>q.decisionId===selected))entry.value=selected;}
      button.textContent = `待决定 (${pending.length})`;
      for (const request of all) {
        const node = shown.get(request.decisionId)?.node;
        if (node?.isConnected && shown.get(request.decisionId).key !== JSON.stringify([request,effects.get(request.decisionId)])) render(request,false);
      }
    },
    clear() { epoch++; pending = []; pageRequests=[]; restored = {}; drafts.clear(); shown.clear(); effects.clear(); button.textContent = '待决定 (0)'; if(entry)entry.replaceChildren(); },
    inspect() { return pending.map(r => ({ decisionId: r.decisionId, revision: r.revision, status: r.status })); },
    snapshot() { return Object.fromEntries([...drafts].map(([id, d]) => [id, d.exportDraft()])); },
    restore(values) {
      if (!values || typeof values !== 'object' || Object.keys(values).length > 64) return;
      restored = values;
      for (const r of pending) if (shown.get(r.decisionId)?.node?.isConnected && !drafts.get(r.decisionId)?.edited) {
        shown.get(r.decisionId).key = null; render(r,false);
      }
    }
  };
}
